const community=document.createElement('div');community.className='status';community.innerHTML=`<h2>Importar conexões compartilhadas</h2><p>Use esta opção quando já tiver um mapa com conexões, um arquivo exportado ou um feed público. Uma conta no Portaler não garante acesso a mapas. Nenhum desses dados é obrigatório para usar a busca de preços ou as rotas terrestres acima.</p><p>Importe uma resposta JSON autorizada do Portaler ou um feed compatível da sua comunidade. Um link comum da página do mapa abre o site externo; não é necessariamente um feed JSON. Nenhuma senha ou token é necessário para importar um arquivo.</p><div class="controls"><label>Servidor dos dados<select id="feed-server"><option value="">Confirme o servidor</option><option value="AMERICA">Américas</option></select></label><label>Fonte / evidência dos dados<input id="feed-source" type="url" placeholder="https://… link da origem"></label><label>Importar conexões JSON<input type="file" id="feed-file" accept="application/json,.json"></label></div><div class="controls"><label>URL de feed público JSON<input id="feed-url" type="url" placeholder="https://…/connections.json"></label><button id="feed-refresh" class="ghost">Ler / atualizar feed público</button></div><div id="feed-status" role="status">Nenhum feed conectado. Apenas links/arquivos acessíveis a você podem ser importados. URLs com tokens não devem ser usadas neste campo.</div><details><summary class="details">Formatos e limites da importação</summary><p>Compatível com connections/links contendo from, to, expires e observed opcionais; respostas Portaler.app com portalConnections/info/fromZone/toZone/expiringDate; e Modern Portaler com connection/expiresUtc. Dados sem expiração futura são descartados. Conexões sem horário de observação exibem “importado”, nunca uma observação inventada. A confirmação de Américas é obrigatória; indicação explícita de outro servidor é rejeitada.</p><p>Um feed público precisa permitir leitura pelo navegador (CORS). Este site estático não contorna login, permissões ou restrições de outro serviço. Links privados, tokens e dados da guilda não são enviados ao GitHub. Dados importados ficam no navegador e entram no seu backup local.</p><p>Para assinalar uma saída da rede para o continente Royal, o feed normalizado pode usar fromRoyal:true ou toRoyal:true. Não presumimos que um nome desconhecido de zona pertença ao continente Royal.</p><pre style="white-space:pre-wrap">{"server":"AMERICA","connections":[{"from":"NOME_REAL_DA_ZONA","to":"NOME_REAL_DO_DESTINO","observed":"DATA_REAL_UTC","expires":"EXPIRACAO_REAL_UTC","toRoyal":true}]}</pre><p>O exemplo acima é apenas o esquema; não contém conexões utilizáveis.</p></details>`;
$('portal').before(community);
function mergeCommunity(data,source){const result=ForgeSearch.importConnections(data,source,$('feed-server').value);const keys=new Set(result.connections.map(l=>[l.from.toLowerCase(),l.to.toLowerCase()].sort().join('|')));links=links.filter(l=>!(l.source===source&&keys.has([l.from.toLowerCase(),l.to.toLowerCase()].sort().join('|'))));links.push(...result.connections);persist();drawLinks();$('feed-status').textContent=`${result.connections.length} conexões válidas importadas; ${result.skipped} entradas descartadas por servidor, expiração ou dados insuficientes. Importação ${fmtDate(Date.now())}. Nenhuma verificação independente de autenticidade foi realizada.`;$('route').click()}
$('feed-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2e6)throw Error('Arquivo maior que 2 MB. Exporte apenas conexões.');mergeCommunity(JSON.parse(await file.text()),$('feed-source').value.trim())}catch(e){$('feed-status').textContent='Importação não concluída: '+e.message}};
$('feed-refresh').onclick=async()=>{const button=$('feed-refresh');button.disabled=true;try{const url=new URL($('feed-url').value);if(url.protocol!=='https:'||url.username||url.password||/[?&](token|key|secret|access_token)=/i.test(url.href))throw Error('Use uma URL HTTPS de feed público sem credenciais.');if($('feed-server').value!=='AMERICA')throw Error('Confirme Américas primeiro.');$('feed-status').textContent='Lendo feed público…';const r=await fetch(url.href,{credentials:'omit',cache:'no-store',signal:AbortSignal.timeout(20000)});if(!r.ok)throw Error('HTTP '+r.status);const raw=await r.text();if(raw.length>2e6)throw Error('Feed maior que 2 MB');mergeCommunity(JSON.parse(raw),url.href)}catch(e){$('feed-status').textContent='Não foi possível ler o feed: '+e.message+'. Verifique URL JSON, acesso e CORS. Você também pode importar o arquivo.'}finally{button.disabled=false}};
const drawLinksBeforeImport=drawLinks;drawLinks=function(){drawLinksBeforeImport();document.querySelectorAll('#links .piece').forEach((p,i)=>{const l=links[i];if(l.observationKind==='retrieved'){const s=p.querySelector('small');if(s)s.innerHTML=s.innerHTML.replace('observado ','importado (observação não informada) ')}if(l.fromRoyal||l.toRoyal)p.insertAdjacentHTML('beforeend','<small>Saída Royal indicada pela fonte</small>')})};drawLinks();

